            build_state_only_cell_map_v4().map_err(|_|
                        AtomicStateOnlyRegistryErrorV3::Layout)?;
        let mut cells = Vec::new();
        for boundary in merkle_boundary_layout() {
            cells.push(map.map(boundary.path_bit).ok_or(AtomicStateOnlyRegistryErrorV3::Layout)?);
            for source in
                boundary.current.into_iter().chain(boundary.left).chain(boundary.right).chain(boundary.sibling)
                {
                cells.push(map.map(source).ok_or(AtomicStateOnlyRegistryErrorV3::Layout)?);
            }
        }
