    fn allocate_atomic_path_component(occupied: &mut Vec<TraceCell>,
        producer_arity: &mut [u8; 1024], consumer_arity: &mut [u8; 1024],
        consumer_endpoints: u8)
        ->
            Result<(TraceCell, [TraceCell; DIGEST_ELEMS]),
            AtomicStateOnlyRegistryErrorV3> {
        let (row, cells) =
            (STATE_ONLY_AUX_ROW_START..STATE_ONLY_AUX_ROW_START +
                                    STATE_ONLY_AUX_ROW_COUNT).find_map(|row|
                            {
                                if producer_arity[row] != 0 ||
                                        consumer_arity[row].saturating_add(consumer_endpoints) > 2 {
                                    return None;
                                }
                                let free =
                                    (0..STATE_ONLY_C1_COLUMNS).map(|column|
                                                        TraceCell {
                                                            row: row as u16,
                                                            column: column as u8,
                                                        }).filter(|cell|
                                                    !occupied.contains(cell)).take(1 +
                                                DIGEST_ELEMS).collect::<Vec<_>>();
                                (free.len() == 1 + DIGEST_ELEMS).then_some((row, free))
                            }).ok_or(AtomicStateOnlyRegistryErrorV3::Layout)?;
        let bit = cells[0];
        let digest = core::array::from_fn(|limb| cells[1 + limb]);
        occupied.extend(cells);
        producer_arity[row] += 2;
        consumer_arity[row] += consumer_endpoints;
        Ok((bit, digest))
    }
    pub fn atomic_state_only_path_aux_layout_v3()
        ->
            Result<[AtomicPathAuxLevelV3; ATOMIC_PAYMENT_TREE_DEPTH],
            AtomicStateOnlyRegistryErrorV3> {
        let map =
            build_state_only_cell_map_v4().map_err(|_|
                        AtomicStateOnlyRegistryErrorV3::Layout)?;
        let removed = old_boundary_cells()?;
        let mut occupied =
            state_only_required_old_cells_v4().into_iter().filter_map(|old|
                            map.map(old)).filter(|cell|
                        {
                            usize::from(cell.row) >= STATE_ONLY_AUX_ROW_START &&
                                    usize::from(cell.row) <
                                        STATE_ONLY_AUX_ROW_START + STATE_ONLY_AUX_ROW_COUNT &&
                                !removed.contains(cell)
                        }).collect::<Vec<_>>();
        occupied.sort_unstable_by_key(|cell| (cell.row, cell.column));
        occupied.dedup();
        let source = copy_layout();
        let old_by_id = source.links;
        let state_only =
            state_only_copy_layout_v4().map_err(|_|
                        AtomicStateOnlyRegistryErrorV3::Layout)?;
        let mut producer_arity = [0u8; 1024];
        let mut consumer_arity = [0u8; 1024];
        for (link, source_id) in
            state_only.links.into_iter().zip(state_only.source_link_ids) {
            let old =
                old_by_id.iter().find(|candidate|
                                candidate.id ==
                                    source_id).ok_or(AtomicStateOnlyRegistryErrorV3::Layout)?;
            if old.kind == CopyLinkKind::MerkleLevel ||
                        tuple_touches_replaced_path(old.producer) ||
                    tuple_touches_replaced_path(old.consumer) {
                continue;
            }
            producer_arity[usize::from(link.producer_row)] += 1;
            consumer_arity[usize::from(link.consumer_row)] += 1;
        }
        let mut layouts = Vec::with_capacity(ATOMIC_PAYMENT_TREE_DEPTH);
        for level in 0..ATOMIC_PAYMENT_TREE_DEPTH {
            let (input_bit, input_current) =
                allocate_atomic_path_component(&mut occupied,
                        &mut producer_arity, &mut consumer_arity, 1)?;
            let (output_bit, output_current) =
                allocate_atomic_path_component(&mut occupied,
                        &mut producer_arity, &mut consumer_arity, 2)?;
            let (sibling_bit, sibling) =
                allocate_atomic_path_component(&mut occupied,
                        &mut producer_arity, &mut consumer_arity, 1)?;
            layouts.push(AtomicPathAuxLevelV3 {
                    level: level as u8,
                    input_bit,
                    input_current,
                    output_bit,
                    output_current,
                    sibling_bit,
                    sibling,
                });
        }
        layouts.try_into().map_err(|_| AtomicStateOnlyRegistryErrorV3::Layout)
    }
    fn tuple_touches_replaced_path(tuple: CopyTuple) -> bool {
        tuple.limbs.into_iter().any(|limb|
                {
                    let TupleLimb::Cell(cell) = limb else { return false; };
                    let row = usize::from(cell.row);
                    row < 49 * BLOCK_ROWS &&
                        (4..=43).contains(&(row / BLOCK_ROWS))
                })
    }
    fn trace_digest_cells(block: usize, local_row: usize)
        -> [TraceCell; DIGEST_ELEMS] {
        core::array::from_fn(|limb|
                TraceCell {
                    row: (block * BLOCK_ROWS + local_row) as u16,
                    column: limb as u8,
                })
    }
    fn path_left_cells(block: usize) -> [TraceCell; DIGEST_ELEMS] {
        trace_digest_cells(block,
            crate::state_only_trace::STATE_ONLY_ABSORPTION_ROW_IN_BLOCK)
    }
    fn path_right_cells(block: usize) -> [TraceCell; DIGEST_ELEMS] {
        core::array::from_fn(|limb|
                TraceCell {
                    row: (block * BLOCK_ROWS) as u16,
                    column: (DIGEST_ELEMS + limb) as u8,
                })
    }
    pub fn build_atomic_state_only_registry_v3()
        -> Result<AtomicStateOnlyRegistryV3, AtomicStateOnlyRegistryErrorV3> {
        let path_aux = atomic_state_only_path_aux_layout_v3()?;
        let source = copy_layout();
        let old_by_id = source.links;
        let state_only =
            state_only_copy_layout_v4().map_err(|_|
                        AtomicStateOnlyRegistryErrorV3::Layout)?;
        let mut links = Vec::new();
        let mut next_tag = 1u32;
        for (link, source_id) in
            state_only.links.into_iter().zip(state_only.source_link_ids) {
            let old =
                old_by_id.iter().find(|candidate|
                                candidate.id ==
                                    source_id).ok_or(AtomicStateOnlyRegistryErrorV3::Layout)?;
            if old.kind == CopyLinkKind::MerkleLevel ||
                        tuple_touches_replaced_path(old.producer) ||
                    tuple_touches_replaced_path(old.consumer) {
                continue;
            }
            let id = links.len() as u16;
            links.push(AtomicCopyLinkV3 {
                    id,
                    tag: M31(next_tag),
                    kind: AtomicCopyLinkKindV3::Retained(link.kind),
                    producer: tuple_from_generic(link.producer),
                    consumer: tuple_from_generic(link.consumer),
                });
            next_tag += 1;
        }
        let retained_links = links.len();
        let mut path_current_links = 0usize;
        let mut path_selection_links = 0usize;
        let mut path_bit_alias_links = 0usize;
        for level in 0..ATOMIC_PAYMENT_TREE_DEPTH {
            let aux = path_aux[level];
            for output in [false, true] {
                let block =
                    if output {
                        ATOMIC_STATE_ONLY_OUTPUT_PATH_BLOCK_START + level
                    } else { ATOMIC_STATE_ONLY_INPUT_PATH_BLOCK_START + level };
                let previous_block =
                    if level == 0 {
                        if output { 48 } else { 3 }
                    } else { block - 1 };
                let current_cells =
                    if output { aux.output_current } else { aux.input_current };
                let bit_cell =
                    if output { aux.output_bit } else { aux.input_bit };
                links.push(AtomicCopyLinkV3 {
                        id: links.len() as u16,
                        tag: M31(next_tag),
                        kind: AtomicCopyLinkKindV3::PathCurrent {
                            output,
                            level: level as u8,
                        },
                        producer: digest_tuple(trace_digest_cells(previous_block,
                                crate::state_only_trace::STATE_ONLY_FINAL_ROW_IN_BLOCK)),
                        consumer: digest_tuple(current_cells),
                    });
                next_tag += 1;
                path_current_links += 1;
                let selection_tag = M31(next_tag);
                next_tag += 1;
                links.push(AtomicCopyLinkV3 {
                        id: links.len() as u16,
                        tag: selection_tag,
                        kind: AtomicCopyLinkKindV3::PathSelect {
                            output,
                            level: level as u8,
                            item: 0,
                        },
                        producer: selected_digest_tuple(cell(bit_cell),
                            current_cells, M31::ZERO),
                        consumer: selected_digest_tuple(AtomicTupleLimbV3::Constant(M31::ZERO),
                            path_left_cells(block), M31::ZERO),
                    });
                links.push(AtomicCopyLinkV3 {
                        id: links.len() as u16,
                        tag: selection_tag,
                        kind: AtomicCopyLinkKindV3::PathSelect {
                            output,
                            level: level as u8,
                            item: 1,
                        },
                        producer: selected_digest_tuple(affine_cell(aux.sibling_bit,
                                M31::ZERO.sub(M31::ONE), M31::ONE), aux.sibling, M31::ZERO),
                        consumer: selected_digest_tuple(AtomicTupleLimbV3::Constant(M31::ONE),
                            path_right_cells(block),
                            M31::ZERO.sub(MERKLE_NODE_COMPRESSION_V3_TWEAK)),
                    });
                path_selection_links += 2;
            }
            for (hop, producer, consumer) in
                [(0u8, aux.input_bit, aux.output_bit),
                        (1u8, aux.output_bit, aux.sibling_bit)] {
                links.push(AtomicCopyLinkV3 {
                        id: links.len() as u16,
                        tag: M31(next_tag),
                        kind: AtomicCopyLinkKindV3::PathBitAlias {
                            level: level as u8,
                            hop,
                        },
                        producer: scalar_tuple(cell(producer), producer.row),
                        consumer: scalar_tuple(cell(consumer), consumer.row),
                    });
                next_tag += 1;
                path_bit_alias_links += 1;
            }
        }
        let registry =
            AtomicStateOnlyRegistryV3 {
                links,
                path_aux,
                retained_links,
                path_current_links,
                path_selection_links,
                path_bit_alias_links,
            };
        endpoint_slots(&registry)?;
        Ok(registry)
    }
