    fn endpoint_slots(registry: &AtomicStateOnlyRegistryV3)
        -> Result<EndpointSlots, AtomicStateOnlyRegistryErrorV3> {
        let mut slots =
            EndpointSlots { producer: [0; 1024], consumer: [0; 1024] };
        for link in &registry.links {
            for (tuple, counts) in
                [(link.producer, &mut slots.producer),
                        (link.consumer, &mut slots.consumer)] {
                let row = usize::from(tuple_row(tuple, link.id)?);
                if counts[row] >= 2 {
                    return Err(AtomicStateOnlyRegistryErrorV3::EndpointCapacity {
                                row: row as u16,
                            });
                }
                counts[row] += 1;
            }
        }
        Ok(slots)
    }
    fn tuple_value(trace: &StateOnlyTraceFoundation, tuple: AtomicCopyTupleV3)
        -> [M31; POSEIDON2_WIDTH] {
        tuple.limbs.map(|limb|
                match limb {
                    AtomicTupleLimbV3::Zero => M31::ZERO,
                    AtomicTupleLimbV3::Constant(value) => value,
                    AtomicTupleLimbV3::AffineCell { cell, scale, offset } =>
                        trace.c1[usize::from(cell.column)][usize::from(cell.row)].mul(scale).add(offset),
                })
    }
    pub fn atomic_state_only_copy_rows_v3(registry:
            &AtomicStateOnlyRegistryV3, trace: &AtomicStateOnlyTraceV3,
        lambda: QM31)
        -> Result<Vec<CopyLogUpRow>, AtomicStateOnlyRegistryErrorV3> {
        atomic_state_only_copy_rows_from_foundation_v3(registry, &trace.trace,
            lambda)
    }
    /// Build the atomic copy rows from the committed foundation alone.  The
    /// metadata-rich `AtomicStateOnlyTraceV3` wrapper is intentionally not needed
    /// after relation-free masks have been applied to the committed columns.
    pub fn atomic_state_only_copy_rows_from_foundation_v3(registry:
            &AtomicStateOnlyRegistryV3, trace: &StateOnlyTraceFoundation,
        lambda: QM31)
        -> Result<Vec<CopyLogUpRow>, AtomicStateOnlyRegistryErrorV3> {
        endpoint_slots(registry)?;
        let empty =
            CopyLogUpRow {
                producer_values: [QM31::ZERO; 2],
                producer_weights: [M31::ZERO; 2],
                consumer_values: [QM31::ZERO; 2],
                consumer_weights: [M31::ZERO; 2],
            };
        let mut rows = ::alloc::vec::from_elem(empty, 1024);
        for link in &registry.links {
            for (tuple, producer) in
                [(link.producer, true), (link.consumer, false)] {
                let row_index = usize::from(tuple_row(tuple, link.id)?);
                let row = &mut rows[row_index];
                let (values, weights) =
                    if producer {
                        (&mut row.producer_values, &mut row.producer_weights)
                    } else {
                        (&mut row.consumer_values, &mut row.consumer_weights)
                    };
                let slot =
                    weights.iter().position(|weight|
                                    *weight ==
                                        M31::ZERO).ok_or(AtomicStateOnlyRegistryErrorV3::EndpointCapacity {
                                row: tuple_row(tuple, link.id)?,
                            })?;
                values[slot] =
                    compress_tagged_tuple(link.tag, &tuple_value(trace, tuple),
                        lambda);
                weights[slot] = M31::ONE;
            }
        }
        Ok(rows)
    }
    /// Build the unique atomic-v3 LogUp helper bound by `lambda,chi`.
    pub fn build_atomic_state_only_copy_helper_v3(trace:
            &StateOnlyTraceFoundation, lambda: QM31, chi: QM31)
        -> Result<Vec<QM31>, AtomicStateOnlyRegistryErrorV3> {
        let registry = build_atomic_state_only_registry_v3()?;
        let rows =
            atomic_state_only_copy_rows_from_foundation_v3(&registry, trace,
                    lambda)?;
        build_copy_logup_helper(&rows,
                chi).map_err(|_|
                AtomicStateOnlyRegistryErrorV3::CopyImbalance)
    }
