    /// Diagnostic-only internal boundaries for the exact atomic-v3 terminal.
    /// This duplicates the production expression deliberately and is pinned to
    /// it by fresh random-QM31 identity tests. It changes no proof or challenge.
    #[allow(clippy::too_many_arguments)]
    #[inline(never)]
    pub fn atomic_state_only_selected_masked_terminal_value_compiled_with_diagnostic_trace_v3<F>(statement:
            &AtomicPaymentStatementV4,
        claims: &[QM31; ATOMIC_SELECTED_TERMINAL_CLAIMS], point: &[QM31; 10],
        lambda: QM31, chi: QM31, theta: QM31, zerocheck_point: &[QM31; 10],
        mu: QM31, eta: QM31, mut trace: F)
        -> Result<QM31, StateOnlyTerminalError> where
        F: FnMut(StateOnlyTerminalDiagnosticPhase) {
        if statement.spend.fee >= VALUE_LIMIT {
            return Err(StateOnlyTerminalError::PublicFeeOutOfRange);
        }
        let openings =
            StateOnlyPoseidonOpenings {
                z: core::array::from_fn(|column|
                        atomic_selected_claim(claims, 0, column)),
                succ_z: core::array::from_fn(|column|
                        atomic_selected_claim(claims, 1, column)),
                xor12_z: core::array::from_fn(|column|
                        atomic_selected_claim(claims, 2, column)),
            };
        let mask_only =
            core::array::from_fn(|column|
                    atomic_selected_claim(claims, 0, C1_COLUMNS + column));
        let selectors = AtomicCrossSelectors::boxed_at_point(point);
        trace(StateOnlyTerminalDiagnosticPhase::Prepared);
        let poseidon =
            evaluate_state_only_poseidon_oracle_projected(&openings,
                &selectors.poseidon());
        trace(StateOnlyTerminalDiagnosticPhase::Poseidon);
        let semantic =
            atomic_semantic_packed_impl(statement, &openings,
                selectors.as_ref(), &mut trace);
        let h1_z =
            atomic_selected_claim(claims, 0, ATOMIC_SELECTED_H1_COLUMN);
        let copy =
            atomic_copy_lane_from_routing_impl(&openings.z, h1_z,
                    &selectors.copy, lambda, chi, &mut trace).0;
        let prepared_theta = PreparedQm31Multiplier::new(theta);
        let mut composition = copy;
        for lane in semantic.into_iter().rev() {
            composition = prepared_theta.mul(composition).add(lane);
        }
        for lane in poseidon.into_iter().rev() {
            composition = prepared_theta.mul(composition).add(lane);
        }
        let original =
            atomic_equality_value(zerocheck_point,
                        point).mul(composition).add(mu.mul(h1_z));
        trace(StateOnlyTerminalDiagnosticPhase::CompositionEquality);
        let mask =
            state_only_selected_mask_value(&openings.z, &mask_only,
                atomic_selected_claim(claims, 0, ATOMIC_SELECTED_G_COLUMN),
                point);
        trace(StateOnlyTerminalDiagnosticPhase::Mask);
        let output = mask.add(eta.mul(original));
        trace(StateOnlyTerminalDiagnosticPhase::Final);
        Ok(output)
    }
