    pub fn build_payment_helpers_v4(trace: &SpendTraceV4, lambda: QM31,
        chi: QM31) -> Result<PaymentHelpersV4, ConstraintBuildError> {
        if trace.c1.iter().any(|column| column.len() != TRACE_ROWS) {
            return Err(ConstraintBuildError::Shape);
        }
        let mut copy_rows =
            ::alloc::vec::from_elem(CopyLogUpRow {
                    producer_values: [QM31::ZERO; 2],
                    producer_weights: [M31::ZERO; 2],
                    consumer_values: [QM31::ZERO; 2],
                    consumer_weights: [M31::ZERO; 2],
                }, TRACE_ROWS);
        let mut endpoint_error = None;
        visit_copy_links(|link|
                {
                    if endpoint_error.is_some() { return; }
                    let producer_row = usize::from(link.producer_row);
                    let consumer_row = usize::from(link.consumer_row);
                    let producer =
                        crate::logup::compress_tagged_tuple(link.tag,
                            &tuple_value(trace, link.producer), lambda);
                    let consumer =
                        crate::logup::compress_tagged_tuple(link.tag,
                            &tuple_value(trace, link.consumer), lambda);
                    {
                        let row = &mut copy_rows[producer_row];
                        if let Err(error) =
                                insert_copy_endpoint(&mut row.producer_values,
                                    &mut row.producer_weights, producer, producer_row) {
                            endpoint_error = Some(error);
                            return;
                        }
                    }
                    {
                        let row = &mut copy_rows[consumer_row];
                        if let Err(error) =
                                insert_copy_endpoint(&mut row.consumer_values,
                                    &mut row.consumer_weights, consumer, consumer_row) {
                            endpoint_error = Some(error);
                        }
                    }
                });
        if let Some(error) = endpoint_error { return Err(error); }
        let aux = witness_aux_layout();
        let range_rows =
            (0..TRACE_ROWS).map(|row|
                        {
                            let producer_weights =
                                if row == INPUT_VALUE_RANGE_ROW ||
                                        row == OUTPUT_VALUE_RANGE_ROW {
                                    [M31::ONE; 3]
                                } else { [M31::ZERO; 3] };
                            RangeLogUpRow {
                                producer_values: core::array::from_fn(|index|
                                        lift(trace.c1[index][row])),
                                producer_weights,
                                consumer_value: lift(M31(row as u32)),
                                consumer_weight: trace.c1[MULTIPLICITY_COLUMN][row],
                            }
                        }).collect::<Vec<_>>();
        if false {
            match (&read_cell(trace, aux.input_value_limbs[0]),
                    &trace.c1[0][INPUT_VALUE_RANGE_ROW]) {
                (left_val, right_val) => {
                    if !(*left_val == *right_val) {
                        let kind = ::core::panicking::AssertKind::Eq;
                        ::core::panicking::assert_failed(kind, &*left_val,
                            &*right_val, ::core::option::Option::None);
                    }
                }
            };
        };
        if false {
            match (&read_cell(trace, aux.output_value_limbs[0]),
                    &trace.c1[0][OUTPUT_VALUE_RANGE_ROW]) {
                (left_val, right_val) => {
                    if !(*left_val == *right_val) {
                        let kind = ::core::panicking::AssertKind::Eq;
                        ::core::panicking::assert_failed(kind, &*left_val,
                            &*right_val, ::core::option::Option::None);
                    }
                }
            };
        };
        let h1 = build_copy_logup_helper(&copy_rows, chi)?;
        let h2 = build_range_logup_helper(&range_rows, chi)?;
        Ok(PaymentHelpersV4 { copy_rows, range_rows, h1, h2 })
    }
    pub fn verify_payment_helpers_v4(helpers: &PaymentHelpersV4, chi: QM31)
        -> Result<(), ConstraintBuildError> {
        verify_copy_logup_constraints(&helpers.copy_rows, &helpers.h1, chi)?;
        verify_range_logup_constraints(&helpers.range_rows, &helpers.h2,
                chi)?;
        Ok(())
    }
