    pub const DIRECT_RANGE_BIT_ROW_START: usize = 864;
    pub const DIRECT_RANGE_LIMB_COUNT: usize = 6;
    pub const DIRECT_RANGE_BITS_PER_LIMB: usize = 10;
    pub const DIRECT_RANGE_LIMBS_PER_ROW: usize = 3;
