            let empty = pair_empty_roots();
            let mut append_path =
                Vec::with_capacity(POOL_V1_PAIR_APPEND_PATH_RESIDUAL_COUNT);
            append_append_path_bindings(trace, statement, &empty,
                &mut append_path);
            let terminal = trace_digest(trace, 53);
            let candidate_root =
                core::array::from_fn(|lane|
                        {
                            terminal[lane].sub(statement.candidate_afterstate.next_root[lane])
                        });
            let mut candidate_frontier =
                Vec::with_capacity(POOL_V1_PAIR_CANDIDATE_FRONTIER_RESIDUAL_COUNT);
            for level in 0..POOL_V1_PAIR_TREE_DEPTH {
                let expected =
                    candidate_frontier_expected(trace, statement, &empty,
                        level);
                append_digest_equal(&statement.candidate_afterstate.next_frontier[level],
                    &expected, &mut candidate_frontier);
            }
            let old_index = statement.live_snapshot.next_pair_index;
            let index_sequence =
                [M31(statement.live_snapshot.sequence as
                                    u32).sub(M31(old_index as u32)),
                        M31(statement.candidate_afterstate.next_pair_index as
                                    u32).sub(M31(old_index as u32).add(M31::ONE))];
