        fn project_legacy(trace: &StateOnlyTraceFoundation)
            -> StateOnlyTraceFoundation {
            let mut projected = trace.clone();
            for column in &mut projected.c1 { column[864..].fill(M31::ZERO); }
            for level in 0..21 {
                let source =
                    pool_v1_pair_forest_path_base_row_v1(level).expect("forest path");
                let target =
                    pool_v1_pair_path_base_row_v1(level).expect("legacy path");
                for column in 0..=8 {
                    projected.c1[column][target] = trace.c1[column][source];
                }
                for column in 0..16 {
                    projected.c1[column][target + 1] =
                        trace.c1[column][source + 1];
                }
                let bit = trace.c1[0][source];
                for column in 0..8 {
                    let left = trace.c1[column][source + 1];
                    let right = trace.c1[8 + column][source + 1];
                    projected.c1[column][target ^ 12] =
                        if bit == M31::ZERO { right } else { left };
                }
            }
            for column in 0..16 {
                projected.c1[column][960..976].copy_from_slice(&trace.c1[column][1008..1024]);
            }
            projected
        }
        fn append_new_poseidon_residuals(trace: &StateOnlyTraceFoundation,
            output: &mut Vec<M31>) {
            for block in 54..57 {
                for local_row in 0..11 {
                    let mut input =
                        core::array::from_fn(|lane|
                                cell(trace, block, local_row, lane));
                    if local_row == 0 {
                        for lane in 0..RATE {
                            input[lane] = input[lane].add(cell(trace, block, 12, lane));
                        }
                    }
                    let (_, expected) =
                        evaluate_trace_round_pair(input,
                                local_row).expect("forest Poseidon local row lies in 0..11");
                    for lane in 0..POSEIDON2_WIDTH {
                        output.push(cell(trace, block, local_row + 1,
                                    lane).sub(expected[lane]));
                    }
                }
            }
        }
        fn append_new_node_schedule(trace: &StateOnlyTraceFoundation,
            output: &mut Vec<M31>) {
            for block in 54..57 {
                for lane in 0..RATE {
                    output.push(cell(trace, block, 0, lane));
                }
                for lane in RATE..POSEIDON2_WIDTH {
                    output.push(cell(trace, block, 12, lane));
                }
            }
        }
