        #[inline]
        pub const fn pool_v1_pair_forest_path_base_row_v1(level: usize)
            -> Option<usize> {
            if level >= POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
                return None;
            }
            Some(POOL_V1_PAIR_FOREST_PATH_AUX_ROW_START_V1 +
                        (level / POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK) *
                            POOL_V1_PAIR_TRACE_BLOCK_ROWS +
                    POOL_V1_PAIR_FOREST_PATH_BASE_LOCAL_ROWS_V1[level /
                                POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK][level %
                            POOL_V1_PAIR_DIRECTIONS_PER_AUX_BLOCK])
        }
        #[inline]
        pub const fn pool_v1_pair_forest_membership_hash_block_v1(level:
                usize) -> Option<usize> {
            if level >= POOL_V1_PAIR_FOREST_PRIVATE_DIRECTIONS_V1 {
                None
            } else if level <= 20 {
                Some(4 + level)
            } else { Some(33 + level) }
        }
