        fn lane_root(input: &PoolV1PairInputNoteWitnessV1)
            -> Result<Digest, PoolV1PairTraceErrorV1> {
            let mut current =
                input.pair_leaf.leaf_digest().map_err(PoolV1PairTraceErrorV1::PairLeaf)?;
            for level in 0..20 {
                let sibling = input.membership.siblings[level];
                current =
                    if ((input.membership.index >> level) & 1) == 0 {
                        pool_v1_tree_parent(&current, &sibling)
                    } else { pool_v1_tree_parent(&sibling, &current) };
            }
            Ok(current)
        }
