        pub fn encode_pool_v1_pair_afterstate_verifier_request_v1(request:
                &PoolV1PairAfterstateVerifierRequestV1<'_>)
            -> Result<Vec<u8>, PoolV1PairVerifierTransportErrorV1> {
            if request.statement_payload.is_empty() ||
                    request.statement_payload.len() > u32::MAX as usize {
                return Err(PoolV1PairVerifierTransportErrorV1::InvalidStatementPayloadLength);
            }
            if request.live_snapshot_payload.len() !=
                    super::pair_tree_profile::POOL_V1_PAIR_LIVE_SNAPSHOT_BYTES {
                return Err(PoolV1PairVerifierTransportErrorV1::InvalidLiveSnapshotPayloadLength);
            }
            super::pair_tree_profile::decode_pool_v1_pair_live_snapshot_v1(request.live_snapshot_payload).map_err(|_|
                        PoolV1PairVerifierTransportErrorV1::InvalidLiveSnapshotPayloadLength)?;
            let header =
                encode_binding_header(POOL_V1_PAIR_AFTERSTATE_VERIFIER_REQUEST_MAGIC,
                        &request.binding, request.statement_payload.len() as u32)?;
            let total =
                header.len().checked_add(request.statement_payload.len()).and_then(|length|
                                length.checked_add(request.live_snapshot_payload.len())).ok_or(PoolV1PairVerifierTransportErrorV1::WrongLength)?;
            let mut output = ::alloc::vec::from_elem(0u8, total);
            let statement_end =
                header.len() + request.statement_payload.len();
            output[..header.len()].copy_from_slice(&header);
            output[header.len()..statement_end].copy_from_slice(request.statement_payload);
            output[statement_end..].copy_from_slice(request.live_snapshot_payload);
            Ok(output)
        }
