            let nullifier =
                write_sponge(trace, 24, DOMAIN_NULLIFIER, &nullifier_fields)?;
            if nullifier !=
                    pool_v1_nullifier(&input.nullifier_key, &input.salt) {
                return Err(PoolV1PaymentTraceErrorV1::NullifierParity);
            }
