        pub const POOL_V1_VERIFIER_ENTRY_VERSION: u8 = 2;
        pub const POOL_V1_VERIFIER_ENTRY_BYTES: usize = 192;
        pub const POOL_V1_VERIFIER_ENTRY_NO_RETIREMENT_SLOT: u64 = u64::MAX;
