    fn pow5(value: M31) -> M31 {
        let square = value.mul(value);
        square.mul(square).mul(value)
    }
    #[inline(always)]
    fn apply_mat4(values: &mut [M31]) {
        let t01 = values[0].add(values[1]);
        let t23 = values[2].add(values[3]);
        let t0123 = t01.add(t23);
        let t01123 = t0123.add(values[1]);
        let t01233 = t0123.add(values[3]);
        let out3 = t01233.add(values[0].double());
        let out1 = t01123.add(values[2].double());
        let out0 = t01123.add(t01);
        let out2 = t01233.add(t23);
        values.copy_from_slice(&[out0, out1, out2, out3]);
    }
    #[inline(always)]
    fn external_linear(state: &mut [M31; 16]) {
        for chunk in state.chunks_exact_mut(4) { apply_mat4(chunk); }
        let mut sums = [M31::ZERO; 4];
        for column in 0..4 {
            for row in 0..4 {
                sums[column] = sums[column].add(state[row * 4 + column]);
            }
        }
        for (index, value) in state.iter_mut().enumerate() {
            *value = value.add(sums[index & 3]);
        }
    }
    /// Algebraically identical external layer with one canonical reduction per
    /// output. Each row has coefficient sum seven, so every temporary is far
    /// below the `M31::reduce_u62` bound.
    #[inline(always)]
    fn apply_mat4_lazy(values: &mut [M31]) {
        let a = values[0].0 as u64;
        let b = values[1].0 as u64;
        let c = values[2].0 as u64;
        let d = values[3].0 as u64;
        values[0] = M31::reduce_u62(2 * a + 3 * b + c + d);
        values[1] = M31::reduce_u62(a + 2 * b + 3 * c + d);
        values[2] = M31::reduce_u62(a + b + 2 * c + 3 * d);
        values[3] = M31::reduce_u62(3 * a + b + c + 2 * d);
    }
    #[inline(always)]
    fn external_linear_lazy(state: &mut [M31; 16]) {
        for chunk in state.chunks_exact_mut(4) { apply_mat4_lazy(chunk); }
        let sums: [u64; 4] =
            core::array::from_fn(|column|
                    (0..4).map(|row| state[row * 4 + column].0 as u64).sum());
        for (index, value) in state.iter_mut().enumerate() {
            *value = M31::reduce_u62(value.0 as u64 + sums[index & 3]);
        }
    }
