    impl Selectors {
        fn expand<const N : usize>(coordinates: &[QM31]) -> [QM31; N] {
            let mut weights = [QM31::ZERO; N];
            weights[0] = QM31::ONE;
            let mut len = 1usize;
            for coordinate in coordinates {
                let prepared = PreparedQm31Multiplier::new(*coordinate);
                for index in (0..len).rev() {
                    let parent = weights[index];
                    let right = prepared.mul(parent);
                    weights[2 * index] = parent.sub(right);
                    weights[2 * index + 1] = right;
                }
                len *= 2;
            }
            weights
        }
        fn at_point(point: &[QM31; 10]) -> Self {
            Self {
                high: Self::expand(&point[..6]),
                low: Self::expand(&point[6..]),
            }
        }
        #[inline(always)]
        fn row(&self, row: usize) -> QM31 {
            if false {
                if !(row < TRACE_ROWS) {
                    ::core::panicking::panic("assertion failed: row < TRACE_ROWS")
                };
            };
            self.high[row >> 4].mul(self.low[row & 15])
        }
        fn poseidon(&self) -> StateOnlyPoseidonSelectors {
            StateOnlyPoseidonSelectors {
                block: self.high[..crate::state_only_poseidon::STATE_ONLY_POSEIDON_BLOCKS].iter().copied().fold(QM31::ZERO,
                    QM31::add),
                local: self.low,
            }
        }
        fn copy_active(&self) -> QM31 {
            constants::COMPILED_COPY_ACTIVE_FACTORS.iter().copied().fold(QM31::ZERO,
                |sum, (high_mask, low_mask)|
                    {
                        let high =
                            self.high.iter().copied().enumerate().filter(|(index, _)|
                                        high_mask & (1u64 << index) !=
                                            0).fold(QM31::ZERO, |sum, (_, value)| sum.add(value));
                        let low =
                            self.low.iter().copied().enumerate().filter(|(index, _)|
                                        low_mask & (1u16 << index) !=
                                            0).fold(QM31::ZERO, |sum, (_, value)| sum.add(value));
                        sum.add(high.mul(low))
                    })
        }
    }
