    /// Direct-to-packed semantic evaluation. Packing is linear, so residuals
    /// with a common row selector are packed first and multiplied by that
    /// selector once per occupied four-lane group.
    #[inline(never)]
    fn semantic_packed_impl<F>(public: &SpendPublic,
        openings: &StateOnlyPoseidonOpenings, selectors: &Selectors,
        mut trace: F) -> [QM31; PACKED_SEMANTIC_LANES] where
        F: FnMut(StateOnlySemanticDiagnosticPhase) {
        let mut packed = [QM31::ZERO; PACKED_SEMANTIC_LANES];
        let initial_highs: [QM31; 24] =
            constants::INITIAL_BLOCKS.map(|(row, _, _)|
                    selectors.high[usize::from(row) >> 4]);
        let initial_high_sum =
            initial_highs.iter().copied().fold(QM31::ZERO, QM31::add);
        let initial_selector = selectors.low[0].mul(initial_high_sum);
        for group in 0..4 {
            packed[group] =
                initial_selector.mul(qm31_pack_base4(&openings.z[4 *
                                        group..4 * group + 4]));
        }
        let domain_sum =
            qm31_m31_dot(&initial_highs,
                &constants::INITIAL_BLOCKS.map(|(_, domain, _)| M31(domain)));
        let length_sum =
            qm31_m31_dot(&initial_highs,
                &constants::INITIAL_BLOCKS.map(|(_, _, length)| M31(length)));
        packed[2] =
            packed[2].sub(selectors.low[0].mul(qm31_pack_base4(&[domain_sum,
                                    length_sum, QM31::ZERO, QM31::ZERO])));
        trace(StateOnlySemanticDiagnosticPhase::Initial);
        for mask in [0x00fcu16, 0xff00, 0xfffc] {
            let high_sum =
                constants::ABSORPTION_ZERO_MASKS.iter().copied().enumerate().filter(|(_,
                                candidate)|
                            *candidate ==
                                mask).fold(QM31::ZERO,
                    |sum, (block, _)| sum.add(selectors.high[block]));
            let selector = selectors.low[12].mul(high_sum);
            for group in 0..4 {
                if mask & (0xf << (4 * group)) != 0 {
                    let residuals: [QM31; 4] =
                        core::array::from_fn(|slot|
                                {
                                    let lane = 4 * group + slot;
                                    if mask & (1 << lane) != 0 {
                                        openings.z[lane]
                                    } else { QM31::ZERO }
                                });
                    packed[4 + group] =
                        packed[4 +
                                    group].add(selector.mul(qm31_pack_base4(&residuals)));
                }
            }
        }
        trace(StateOnlySemanticDiagnosticPhase::Absorption);
        let merkle_selector =
            (0..20usize).fold(QM31::ZERO,
                |sum, level|
                    {
                        sum.add(selectors.row(784 + 16 * (level / 4) +
                                    2 * (level % 4)))
                    });
        let bit = openings.z[0];
        let merkle_residuals: [QM31; 17] =
            core::array::from_fn(|index|
                    {
                        if index == 0 {
                            bit.mul(bit.sub(QM31::ONE))
                        } else {
                            let limb = (index - 1) % DIGEST_ELEMS;
                            let current = openings.z[1 + limb];
                            let sibling = openings.xor12_z[limb];
                            let delta = sibling.sub(current);
                            if index <= DIGEST_ELEMS {
                                openings.succ_z[limb].sub(current.add(bit.mul(delta)))
                            } else {
                                openings.succ_z[RATE +
                                            limb].sub(sibling.sub(bit.mul(delta)))
                            }
                        }
                    });
        accumulate_packed_run(&mut packed, 32, &merkle_residuals,
            merkle_selector);
        trace(StateOnlySemanticDiagnosticPhase::Merkle);
        let range_selectors = [selectors.row(864), selectors.row(866)];
        let range_selector = range_selectors[0].add(range_selectors[1]);
        let range_residuals: [QM31; 33] =
            core::array::from_fn(|index|
                    {
                        if index < 30 {
                            let view_index = index / 10;
                            let bit_index = index % 10;
                            let view =
                                match view_index {
                                    0 => &openings.z,
                                    1 => &openings.succ_z,
                                    _ => &openings.xor12_z,
                                };
                            view[bit_index].mul(view[bit_index].sub(QM31::ONE))
                        } else {
                            let view =
                                match index - 30 {
                                    0 => &openings.z,
                                    1 => &openings.succ_z,
                                    _ => &openings.xor12_z,
                                };
                            let reconstructed =
                                (0..10).fold(QM31::ZERO,
                                    |sum, bit_index|
                                        { sum.add(view[bit_index].mul_m31(M31(1 << bit_index))) });
                            view[10].sub(reconstructed)
                        }
                    });
        accumulate_packed_run(&mut packed, 49, &range_residuals,
            range_selector);
        let triple_value =
            openings.z[10].add(openings.succ_z[10].mul_m31(M31(1 <<
                                10))).add(openings.xor12_z[10].mul_m31(M31(1 << 20)));
        let totals =
            [range_selector.mul(openings.z[11].sub(triple_value)),
                    range_selectors[0].mul(openings.z[11].sub(openings.z[12]).sub(lift(M31(public.fee))))];
        add_preweighted_packed_run(&mut packed, 82, &totals);
        trace(StateOnlySemanticDiagnosticPhase::Range);
        for (block, digest) in
            [(43usize, &public.anchor), (45usize, &public.nullifier),
                    (48usize, &public.output_commitment)] {
            let residuals: [QM31; DIGEST_ELEMS] =
                core::array::from_fn(|limb|
                        openings.z[limb].sub(lift(digest[limb])));
            accumulate_packed_run(&mut packed, 84, &residuals,
                selectors.row(block * 16 + 11));
        }
        let assets: [QM31; 2] =
            core::array::from_fn(|lane|
                    {
                        let (row, column) =
                            [constants::INPUT_ASSET_CELL,
                                        constants::OUTPUT_ASSET_CELL][lane];
                        selectors.row(usize::from(row)).mul(openings.z[usize::from(column)].sub(lift(public.asset_id)))
                    });
        add_preweighted_packed_run(&mut packed, 92, &assets);
        trace(StateOnlySemanticDiagnosticPhase::Public);
        packed
    }
