    pub const fn state_only_geometry(prefix: &StateOnlyCandidatePrefix<'_>)
        -> Option<CircleOpeningGeometry> {
        if prefix.shape.profile_id == STATE_ONLY_RATE16_SHAPE.profile_id {
            Some(RATE16_CIRCLE_OPENING_GEOMETRY)
        } else if prefix.shape.profile_id ==
                STATE_ONLY_RATE32_SHAPE.profile_id {
            Some(RATE32_CIRCLE_OPENING_GEOMETRY)
        } else if prefix.shape.profile_id ==
                STATE_ONLY_RATE256_SHAPE.profile_id {
            Some(RATE256_CIRCLE_OPENING_GEOMETRY)
        } else if prefix.shape.profile_id ==
                STATE_ONLY_RATE512_SHAPE.profile_id {
            Some(RATE512_CIRCLE_OPENING_GEOMETRY)
        } else { None }
    }
