    #[inline(never)]
    fn verify_queries_phase(prefix: &StateOnlyCandidatePrefix<'_>,
        schedule: &StateOnlyTranscriptScheduleResult,
        query_powers: &StateOnlyQueryPowers,
        openings: &VerifiedCircleOpenings<'_>,
        geometry: CircleOpeningGeometry, segment: CircleQuerySegment)
        -> Result<(), StateOnlyCandidateVerifyError> {
        let mut final_coefficients = [QM31::ZERO; CANDIDATE_FINAL_POLY_LEN];
        for (coefficient, output) in final_coefficients.iter_mut().enumerate()
            {
            *output =
                prefix.final_coefficient(coefficient).ok_or(StateOnlyRelationVerifyError::PrefixShape)?;
        }
        openings.check_state_only_query_segment_prepared_for_geometry(query_powers,
                schedule.alpha, final_coefficients, segment, geometry)?;
        Ok(())
    }
    fn later_roots(prefix: &StateOnlyCandidatePrefix<'_>)
        -> Result<[[u8; 32]; 3], StateOnlyCandidateVerifyError> {
        let mut roots = [[0u8; 32]; 3];
        for (layer, root) in roots.iter_mut().enumerate() {
            *root =
                prefix.rounds[layer +
                                        1].root.copied().ok_or(StateOnlyRelationVerifyError::PrefixShape)?;
        }
        Ok(roots)
    }
