        build_exceptional_copy_terminal_links();
    pub fn visit_copy_exceptional_terminal_links<F>(mut visitor: F) where
        F: FnMut(CopyTerminalLink) {
        for link in EXCEPTIONAL_COPY_TERMINAL_LINKS { visitor(link); }
    }
